### Tested versions

- 4.3

### System information

Godot v4.3.1.rc (d40fc50f0) - Windows 10.0.22000 - Vulkan (Forward+) - dedicated Quadro P2000 - Intel(R) Xeon(R) Silver 4110 CPU @ 2.10GHz (32 Threads)

### Issue description

```Cpp
class OperatorEvaluatorEqualObject {
public:
    static void evaluate(const Variant &p_left, const Variant &p_right, Variant *r_ret, bool &r_valid) {
        const Object *a = p_left.get_validated_object();
        const Object *b = p_right.get_validated_object();
        *r_ret = a == b;
        r_valid = true;
    }
    static inline void validated_evaluate(const Variant *left, const Variant *right, Variant *r_ret) {
        const Object *a = left->get_validated_object();
        const Object *b = right->get_validated_object();
        *VariantGetInternalPtr<bool>::get_ptr(r_ret) = a == b;
    }
    static void ptr_evaluate(const void *left, const void *right, void *r_ret) {
        PtrToArg<bool>::encode(PtrToArg<Object *>::convert(left) == PtrToArg<Object *>::convert(right), r_ret);
    }
    static Variant::Type get_return_type() { return Variant::BOOL; }
};
```


In the above code, the equality of two Objects is determined by comparing whether the pointers are equal, which is not a problem in itself.
However, in some cases, it is necessary to compare the contents of two Object instances to determine equality. For example, in the following code:
When you want to pass Python objects to Godot's Array or Dictionary through PythonObject, if the Array and Dictionary hold Ref<PythonObject> smart pointers, the equality cannot be determined regardless of the value of py::object _py_object.
```Cpp
class PythonObject : public RefCounted {
    GDCLASS(PythonObject, RefCounted);
public:
    PythonObject() {}
    PythonObject(const PythonObject& v) { _py_object = v._py_object; }
    PythonObject(PythonObject&& v) { _py_object = std::move(v._py_object); }
    PythonObject(const py::object& obj) { _py_object = obj; }
    PythonObject& operator=(PythonObject&& v) { _py_object = std::move(v._py_object); return *this; }
    virtual ~PythonObject() {}
public:
    py::object get_py_object() { return _py_object; }
    void set_py_object(const py::object& obj) { _py_object = obj; }
    operator py::object&() { return _py_object; }
    py::object& operator*() { return _py_object; }
    void operator=(const py::object& obj) { _py_object = obj; }
    bool operator==(const PythonObject& right) const {
        if (this == &right) {
            return true;
        }
        py::object left_obj = this->_py_object;
        py::object right_obj = right._py_object;
        bool b1 = left_obj.get_type().is(right_obj.get_type());
        bool b2 = left_obj.is(right_obj);
        bool b3 = py::cast<bool>(left_obj.attr("__eq__")(left_obj));
        if (b1 && (b2 || b3)) {
            return true;
        }
    }
    bool operator!=(const PythonObject& right) const {
        return!(*this == right);
    }
    bool operator==(const PythonObject* right) const {
        if (this == right) {
            return true;
        }
        py::object left_obj = this->_py_object;
        py::object right_obj = right->_py_object;
        bool b1 = left_obj.get_type().is(right_obj.get_type());
        bool b2 = left_obj.is(right_obj);
        bool b3 = py::cast<bool>(left_obj.attr("__eq__")(left_obj));
        if (b1 && (b2 || b3)) {
            return true;
        }
        return false;
    }

    bool operator!=(const PythonObject* right) const {
        return!(*this == right);
    }
protected:
    py::object _py_object;
};
```

It is hoped that a set of methods can be provided to enable the OperatorEvaluatorEqual operation for custom types, or a method that can receive a callback function in the recursive_equal method of Array and Dictionary, so as to implement the content comparison of custom types.

